+    resize: none;
+    font-family: inherit;
+    outline: none;
+}
+
+.message-input textarea::placeholder {
+    color: #72767d;
+}
+
+.message-input textarea:focus {
+    box-shadow: 0 0 0 1px #5865f2;
+}
+
+.send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 20px;
+    cursor: pointer;
+    font-weight: 600;
+    font-size: 0.85rem;
+    transition: background 0.15s;
+    align-self: flex-end;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
