+}
+
+.close-btn:hover {
+    background: #393c43;
+    color: #fff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    background: #36393f;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-divider {
+    padding: 8px 16px;
+    font-size: 0.75rem;
+    color: #8e9297;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 8px 16px;
+}
+
+.thread-reply {
+    padding: 8px 0;
+    border-bottom: 1px solid #36393f;
+}
+
+.thread-reply:last-child {
+    border-bottom: none;
+}
